{"artifact":{"path":"union-acceptance/cut-identity.test.mjs","text":"import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { scanTerritory } from "../src/scan-territory.mjs";
import { semanticId } from "@emsenn/rmn-semantic-conformance";
import { encodeRelationalValue } from "@emsenn/rmn-semantic-conformance/relational-value";

const NI_SHA256_RE = /^ni:\/\/\/sha-256;[A-Za-z0-9_-]+=*$/u;

function canonicalCutId({ settlement, violationCount, rules, paths }) {
  const payload = encodeRelationalValue({
    profile: "org.emsenn.phase2.cut-frontier-entry.v1",
    settlement,
    violationCount,
    rules: [...rules].sort(),
    paths: [...paths].sort(),
  });
  return semanticId(["ascribe", payload.type, payload.term]);
}

test("canonical-cut-ni-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(
      join(root, "package.json"),
      JSON.stringify({
        name: "test-die",
        "x-agentic-metro-enterprise": {
          "node-id": "test-die",
          "operation-catalog": { left: {}, right: {} },
        },
      })
    );
    const report = scanTerritory(root);
    const entry = report.cutFrontier[0];
    assert.ok(entry, "cut frontier must have at least one entry");
    assert.ok(entry.cutId, "cutFrontier entry must carry a cutId");
    assert.match(entry.cutId, NI_SHA256_RE, "cutId must be RFC 6920 SHA-256 ni URI");
    assert.equal(
      entry.cutId,
      canonicalCutId(entry),
      "cutId must match canonical RMN identity over settlement, violationCount, sorted rules, sorted paths"
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("repeatable-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(
      join(root, "package.json"),
      JSON.stringify({
        name: "test-die",
        "x-agentic-metro-enterprise": {
          "node-id": "test-die",
          "operation-catalog": { left: {}, right: {} },
        },
      })
    );
    const first = scanTerritory(root);
    const second = scanTerritory(root);
    assert.ok(first.cutFrontier[0]?.cutId, "first scan must produce a cutId");
    assert.equal(
      first.cutFrontier[0].cutId,
      second.cutFrontier[0].cutId,
      "repeated scans of identical territory must produce equal cutId"
    );
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("material-change-changes-cut-identity", () => {
  const root = mkdtempSync(join(tmpdir(), "cut-id-"));
  try {
    writeFileSync(
      join(root, "package.json"),
      JSON.stringify({
        name: "test-die",
        "x-agentic-metro-enterprise": {
          "node-id": "test-die",
          "operation-catalog": { left: {}, right: {} },
        },
      })
    );
    const before = scanTerritory(root);
    const idBefore = before.cutFrontier[0]?.cutId;
    assert.ok(idBefore, "initial scan must produce a cutId");

    writeFileSync(
      join(root, "package.json"),
      JSON.stringify({
        name: "test-die",
        "x-agentic-metro-enterprise": {
          "node-id": "test-die",
          "operation-catalog": { left: {}, right: {}, center: {} },
        },
      })
    );
    mkdirSync(join(root, "src"), { recursive: true });
    writeFileSync(join(root, "src", "op.mjs"), "const cfg = { legacyCompatibility: true };\n");

    const after = scanTerritory(root);
    const idAfter = after.cutFrontier[0]?.cutId;
    assert.ok(idAfter, "scan after material change must produce a cutId");
    assert.notEqual(idBefore, idAfter, "cutId must change when cut-frontier material changes");
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
"},"rationale":"Each test reaches the cutId assertion before failing: the incumbent cutFrontier entries carry no cutId field, so assert.ok(entry.cutId) fails in all three tests — a pure behavioral gap, not a fixture or import failure. The independent expected identity in canonical-cut-ni-identity is computed via encodeRelationalValue (canonical CBOR, not sorted JSON) over settlement, violationCount, sorted rules, and sorted paths, then hashed through semanticId to produce the ni URI, satisfying the identity-coverage constraint without ordinal FOUR. The material-change fixture mutates both the catalog (third operation) and adds an operational file with a legacy-switch pattern, guaranteeing that violationCount, rules, and paths all differ between the two frontier entries so assert.notEqual holds against any correct implementation."}

